package com.example.agendapersonal.respaldo;

import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import android.net.Uri;
import com.example.agendapersonal.data.DatabaseHelper;import com.example.agendapersonal.sync.*;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;

/** Copias consistentes y reemplazo transaccional; no cambia el archivo SQLite mientras hay conexiones abiertas. */
public final class GestorRespaldo {
    private static final String FORMATO="AgendaPersonal",CONTROL=EsquemaRespaldo.CONTROL;
    private GestorRespaldo(){}
    public static final class Preparada implements AutoCloseable {
        final File dir,db,meta;final JSONObject manifiesto;
        Preparada(File dir,JSONObject m){this.dir=dir;db=new File(dir,"agenda.db");meta=new File(dir,"manifest.json");manifiesto=m;}
        public String resumen(){JSONObject n=manifiesto.optJSONObject("filas");return "Creada: "+manifiesto.optString("creada")+"\nTareas: "+n.optLong("tareas")+" · Eventos guardados: "+n.optLong("eventos")+"\nCambios de sincronización: "+n.optLong("sync_changes")+"\nIncluye todos los módulos, historiales, recurrencias y datos de origen.\n\nSe reemplazará el contenido local por esta copia. Se conservará una copia interna del estado anterior y la sincronización quedará pausada hasta que vuelvas a iniciar sesión.";}
        @Override public void close(){borrarTemporal(dir);}
    }
    private static File temporal(Context c)throws IOException {File d=new File(c.getCacheDir(),"respaldo_"+UUID.randomUUID());if(!d.mkdirs())throw new IOException("No se pudo preparar espacio para la copia");return d;}
    private static void borrarTemporal(File dir){File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.isFile())f.delete();dir.delete();}
    private static String texto(File f)throws IOException {try(InputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){ArchivoRespaldo.copiar(in,out,1024*1024);return out.toString("UTF-8");}}
    private static void escribir(File f,String texto)throws IOException {try(OutputStream out=new FileOutputStream(f)){out.write(texto.getBytes(StandardCharsets.UTF_8));out.flush();}ArchivoRespaldo.sincronizar(f);}
    private static List<String> columnas(SQLiteDatabase db,String tabla){List<String> n=new ArrayList<>();try(Cursor c=db.rawQuery("PRAGMA table_info("+EsquemaRespaldo.nombre(tabla)+")",null)){while(c.moveToNext())n.add(c.getString(c.getColumnIndexOrThrow("name")));}return n;}
    static Map<String,String> existentes(SQLiteDatabase db)throws IOException {Map<String,String> admitidas=EsquemaRespaldo.tablas(),r=new LinkedHashMap<>();try(Cursor c=db.rawQuery("SELECT name,sql,type FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' AND name<>'android_metadata' AND type IN ('table','view','trigger') ORDER BY name",null)){while(c.moveToNext()){String n=c.getString(0);if(n.equals(CONTROL))continue;String sql=c.getString(1);if(!c.getString(2).equals("table")||!admitidas.containsKey(n)||sql==null||!EsquemaRespaldo.normalizar(sql).equals(EsquemaRespaldo.normalizar(admitidas.get(n))))throw new IOException("La estructura de la base no es compatible: "+n);r.put(n,admitidas.get(n));}}return r;}
    private static List<String> orden(SQLiteDatabase db,Set<String> tablas)throws IOException {List<String> resultado=new ArrayList<>();Set<String>pendientes=new LinkedHashSet<>(tablas);while(!pendientes.isEmpty()){boolean avanzo=false;for(String t:new ArrayList<>(pendientes)){boolean lista=true;try(Cursor c=db.rawQuery("PRAGMA foreign_key_list("+EsquemaRespaldo.nombre(t)+")",null)){while(c.moveToNext()){String padre=c.getString(c.getColumnIndexOrThrow("table"));if(pendientes.contains(padre)&&!padre.equals(t))lista=false;}}if(lista){resultado.add(t);pendientes.remove(t);avanzo=true;}}if(!avanzo)throw new IOException("No se pudo ordenar las relaciones de la copia");}return resultado;}
    static void integridad(SQLiteDatabase db)throws IOException {try(Cursor c=db.rawQuery("PRAGMA integrity_check",null)){if(!c.moveToFirst()||!"ok".equals(c.getString(0)))throw new IOException("La base de la copia está dañada");}try(Cursor c=db.rawQuery("PRAGMA foreign_key_check",null)){if(c.moveToFirst())throw new IOException("La copia tiene relaciones incompletas");}}
    private static long filas(SQLiteDatabase db,String t){try(Cursor c=db.rawQuery("SELECT count(*) FROM "+EsquemaRespaldo.nombre(t),null)){c.moveToFirst();return c.getLong(0);}}
    private static void copiarFilas(SQLiteDatabase origen,SQLiteDatabase destino,String tabla)throws IOException {List<String> campos=columnas(origen,tabla);if(!campos.equals(columnas(destino,tabla)))throw new IOException("Campos incompatibles en "+tabla);StringBuilder nombres=new StringBuilder(),marcas=new StringBuilder();for(String campo:campos){if(nombres.length()>0){nombres.append(',');marcas.append(',');}nombres.append(EsquemaRespaldo.nombre(campo));marcas.append('?');}try(Cursor rows=origen.rawQuery("SELECT "+nombres+" FROM "+EsquemaRespaldo.nombre(tabla),null);SQLiteStatement insert=destino.compileStatement("INSERT INTO "+EsquemaRespaldo.nombre(tabla)+" ("+nombres+") VALUES ("+marcas+")")){while(rows.moveToNext()){insert.clearBindings();for(int i=0;i<campos.size();i++)switch(rows.getType(i)){case Cursor.FIELD_TYPE_NULL:insert.bindNull(i+1);break;case Cursor.FIELD_TYPE_INTEGER:insert.bindLong(i+1,rows.getLong(i));break;case Cursor.FIELD_TYPE_FLOAT:insert.bindDouble(i+1,rows.getDouble(i));break;case Cursor.FIELD_TYPE_BLOB:insert.bindBlob(i+1,rows.getBlob(i));break;default:insert.bindString(i+1,rows.getString(i));}insert.executeInsert();}}}
    private static JSONObject preferencias(Context c,SQLiteDatabase db)throws JSONException {String owner=meta(db,"sync_meta","cuenta");android.content.SharedPreferences identidad=c.getSharedPreferences("agenda_identidad",Context.MODE_PRIVATE);if(owner==null)owner=identidad.getString("owner_id",null);if(owner==null){owner=UUID.randomUUID().toString();identidad.edit().putString("owner_id",owner).commit();}return new JSONObject().put("owner_local",owner).put("escala_radar",c.getSharedPreferences("agenda_preferencias",Context.MODE_PRIVATE).getInt("escala_radar",10)).put("flotante",c.getSharedPreferences("agenda_avisos",Context.MODE_PRIVATE).getBoolean("flotante",false));}
    static JSONObject snapshot(Context c,SQLiteDatabase origen,File dir)throws Exception {Map<String,String> tablas=existentes(origen);File archivo=new File(dir,"agenda.db");JSONObject cantidades=new JSONObject();try(SQLiteDatabase copia=SQLiteDatabase.openOrCreateDatabase(archivo,null)){copia.setForeignKeyConstraintsEnabled(true);copia.beginTransaction();try{for(String t:orden(origen,tablas.keySet())){copia.execSQL(tablas.get(t));copiarFilas(origen,copia,t);cantidades.put(t,filas(origen,t));}copia.setVersion(origen.getVersion());integridad(copia);copia.setTransactionSuccessful();}finally{copia.endTransaction();}}ArchivoRespaldo.sincronizar(archivo);JSONObject m=new JSONObject().put("formato",FORMATO).put("version",1).put("base_version",origen.getVersion()).put("creada",Instant.now().toString()).put("sha256",ArchivoRespaldo.sha256(archivo)).put("filas",cantidades).put("preferencias",preferencias(c,origen));escribir(new File(dir,"manifest.json"),m.toString());return m;}
    public static void exportar(Context c,Uri uri,char[] password)throws Exception {File dir=temporal(c);try{try(DatabaseHelper h=new DatabaseHelper(c)){SQLiteDatabase db=h.getWritableDatabase();db.beginTransaction();try{snapshot(c,db,dir);db.setTransactionSuccessful();}finally{db.endTransaction();}}guardarArchivo(c,uri,dir,password);}finally{Arrays.fill(password,'\0');borrarTemporal(dir);}}
    private static void guardarArchivo(Context c,Uri uri,File dir,char[] password)throws IOException {File zip=new File(dir,"paquete.zip"),cifrado=new File(dir,"paquete.agendabak");ArchivoRespaldo.empaquetar(new File(dir,"agenda.db"),new File(dir,"manifest.json"),zip);try(InputStream in=new FileInputStream(zip);OutputStream out=new FileOutputStream(cifrado)){CifradoRespaldo.cifrar(in,out,password);}ArchivoRespaldo.sincronizar(cifrado);try(InputStream in=new FileInputStream(cifrado);OutputStream out=c.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No se pudo abrir el destino");ArchivoRespaldo.copiar(in,out,CifradoRespaldo.LIMITE+1024*1024);out.flush();}}
    public static Preparada preparar(Context c,Uri uri,char[] password)throws Exception {File dir=temporal(c);boolean lista=false;try{File zip=new File(dir,"paquete.zip");try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(zip)){if(in==null)throw new IOException("No se pudo abrir el archivo");CifradoRespaldo.descifrar(in,out,password);}ArchivoRespaldo.extraer(zip,new File(dir,"agenda.db"),new File(dir,"manifest.json"));JSONObject m=new JSONObject(texto(new File(dir,"manifest.json")));Preparada p=new Preparada(dir,m);validar(c,p);lista=true;return p;}finally{Arrays.fill(password,'\0');if(!lista)borrarTemporal(dir);}}
    private static void validar(Context c,Preparada p)throws Exception {JSONObject m=p.manifiesto;if(!FORMATO.equals(m.getString("formato"))||m.getInt("version")!=1||m.getInt("base_version")!=2)throw new IOException("Esta copia necesita una versión compatible de Agenda Personal");Instant.parse(m.getString("creada"));if(!ArchivoRespaldo.sha256(p.db).equals(m.getString("sha256")))throw new IOException("La copia está incompleta o dañada");try(SQLiteDatabase db=SQLiteDatabase.openDatabase(p.db.getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY)){if(db.getVersion()!=2)throw new IOException("Versión de base incompatible");Map<String,String> tablas=existentes(db);for(String sql:DatabaseHelper.esquemaTablasRespaldo()){String nombre=sql.substring(13,sql.indexOf('(')).trim();if(!tablas.containsKey(nombre))throw new IOException("Falta una tabla de la copia: "+nombre);}JSONObject n=m.getJSONObject("filas");if(n.length()!=tablas.size())throw new IOException("Resumen de tablas incompleto");for(String t:tablas.keySet())if(n.getLong(t)!=filas(db,t))throw new IOException("Cantidad de registros incorrecta: "+t);JSONObject prefs=m.getJSONObject("preferencias");ReglasSync.uuid(prefs.getString("owner_local"));int escala=prefs.getInt("escala_radar");if(escala<1||escala>1000000)throw new IOException("Preferencias incompatibles");integridad(db);try(DatabaseHelper h=new DatabaseHelper(c)){comprobarCuenta(h.getReadableDatabase(),db,prefs.getString("owner_local"));}}}
    private static String meta(SQLiteDatabase db,String tabla,String clave){try(Cursor existe=db.rawQuery("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",new String[]{tabla})){if(!existe.moveToFirst())return null;}try(Cursor c=db.query(tabla,new String[]{"valor"},"clave=?",new String[]{clave},null,null,null)){return c.moveToFirst()?c.getString(0):null;}}
    private static void comprobarCuenta(SQLiteDatabase actual,SQLiteDatabase fuente,String propietario)throws IOException {String cuenta=meta(actual,"sync_meta","cuenta"),otra=meta(fuente,"sync_meta","cuenta");if(!ReglasCuentaRespaldo.compatible(cuenta,meta(actual,"sync_meta","proyecto"),otra,meta(fuente,"sync_meta","proyecto"),propietario,meta(actual,"sync_meta","propietario_local"),meta(actual,CONTROL,"propietario_anterior")))throw new IOException("La copia pertenece a otra cuenta o proyecto. No se mezclaron datos");}
    private static void control(SQLiteDatabase db,String clave,String valor){ContentValues v=new ContentValues();v.put("clave",clave);v.put("valor",valor);db.insertWithOnConflict(CONTROL,null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    static void reemplazarTablas(SQLiteDatabase db,SQLiteDatabase fuente)throws Exception {if(!db.inTransaction())throw new IllegalStateException("La restauración debe estar dentro de una transacción");Map<String,String> nuevas=existentes(fuente),actuales=existentes(db);for(String t:orden(fuente,nuevas.keySet()))if(!actuales.containsKey(t))db.execSQL(nuevas.get(t));Map<String,String> todas=existentes(db);List<String> inverso=orden(db,todas.keySet());Collections.reverse(inverso);for(String t:inverso)db.delete(t,null,null);for(String t:orden(fuente,nuevas.keySet()))copiarFilas(fuente,db,t);integridad(db);}
    public static void restaurar(Context c,Preparada p)throws Exception {validar(c,p);CoordinadorSync.de(c).cancelar();File carpeta=new File(c.getFilesDir(),"respaldos_anteriores"),anterior=new File(carpeta,"antes_"+System.currentTimeMillis()+"_"+UUID.randomUUID());if(!anterior.mkdirs())throw new IOException("No se pudo guardar el estado anterior; no se restauró la copia");boolean confirmada=false;try(DatabaseHelper h=new DatabaseHelper(c);SQLiteDatabase fuente=SQLiteDatabase.openDatabase(p.db.getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY)){SQLiteDatabase db=h.getWritableDatabase();db.beginTransaction();try{comprobarCuenta(db,fuente,p.manifiesto.getJSONObject("preferencias").getString("owner_local"));JSONObject estadoAnterior=snapshot(c,db,anterior);reemplazarTablas(db,fuente);db.execSQL("CREATE TABLE IF NOT EXISTS "+CONTROL+" (clave TEXT PRIMARY KEY NOT NULL, valor TEXT NOT NULL)");control(db,"preferencias",p.manifiesto.getJSONObject("preferencias").toString());control(db,"dispositivo",UUID.randomUUID().toString());control(db,"anterior",anterior.getAbsolutePath());control(db,"propietario_anterior",estadoAnterior.getJSONObject("preferencias").getString("owner_local"));control(db,"pendiente","1");db.setTransactionSuccessful();}finally{db.endTransaction();}confirmada=true;}finally{if(!confirmada)borrarTemporal(anterior);}finalizarPendiente(c);}
    /** Puente durable entre el commit SQLite y las preferencias; se repite al iniciar si hubo una interrupción. */
    public static void finalizarPendiente(Context c)throws Exception {try(DatabaseHelper h=new DatabaseHelper(c)){SQLiteDatabase db=h.getWritableDatabase();if(!"1".equals(meta(db,CONTROL,"pendiente")))return;JSONObject prefs=new JSONObject(meta(db,CONTROL,"preferencias"));String owner=meta(db,"sync_meta","cuenta");if(owner==null)owner=prefs.getString("owner_local");new SesionSegura(c).borrar();if(!c.getSharedPreferences("agenda_identidad",Context.MODE_PRIVATE).edit().putString("device_id",meta(db,CONTROL,"dispositivo")).putString("owner_id",owner).commit()||!c.getSharedPreferences("agenda_preferencias",Context.MODE_PRIVATE).edit().putInt("escala_radar",prefs.getInt("escala_radar")).commit()||!c.getSharedPreferences("agenda_avisos",Context.MODE_PRIVATE).edit().clear().putBoolean("flotante",prefs.optBoolean("flotante",false)).commit()||!c.getSharedPreferences("agenda_sync_estado",Context.MODE_PRIVATE).edit().clear().putBoolean("automatico",false).putString("mensaje","Copia restaurada. Iniciá sesión con la cuenta de esta agenda para reanudar la sincronización.").commit())throw new IOException("La copia se restauró. Reiniciá la app para completar su configuración");control(db,"pendiente","0");}c.getSystemService(android.app.NotificationManager.class).cancelAll();c.stopService(new Intent(c,com.example.agendapersonal.avisos.VentanaAvisos.class));com.example.agendapersonal.avisos.ProgramadorAvisos.actualizar(c);}
    public static boolean configuracionPendiente(Context c){try(DatabaseHelper h=new DatabaseHelper(c)){return "1".equals(meta(h.getReadableDatabase(),CONTROL,"pendiente"));}}
    public static boolean hayAnterior(Context c){try(DatabaseHelper h=new DatabaseHelper(c)){String ruta=meta(h.getReadableDatabase(),CONTROL,"anterior");return ruta!=null&&new File(ruta,"agenda.db").isFile();}}
    public static void exportarAnterior(Context c,Uri uri,char[] password)throws Exception {try(DatabaseHelper h=new DatabaseHelper(c)){String ruta=meta(h.getReadableDatabase(),CONTROL,"anterior");File base=new File(c.getFilesDir(),"respaldos_anteriores"),dir=ruta==null?null:new File(ruta);if(dir==null||!dir.getCanonicalFile().getParentFile().equals(base.getCanonicalFile()))throw new IOException("No hay un estado anterior disponible");guardarArchivo(c,uri,dir,password);}finally{Arrays.fill(password,'\0');}}
}
